) {}

export class WebsiteApiDeadlineExceeded extends Schema.TaggedError<WebsiteApiDeadlineExceeded>()(
  "WebsiteApiDeadlineExceeded",
  {
    message: Schema.tag(
      "The request could not finish within ten seconds. Try again when you are ready."
    ),
  }
