const websiteOrigin = "http://127.0.0.1:4196";

it.live("probe", () =>
  Effect.gen(function* () {
    const fs = yield* FileSystem.FileSystem;
    const path = yield* Path.Path;
    const root = path.resolve("../..");
    const load = (dir: string) =>
      Effect.gen(function* () {
        const files = yield* fs.glob("**/*.js", { root: dir });
        return Record.fromEntries(
          yield* Effect.forEach(files, (file) =>
            fs.readFileString(path.join(dir, file)).pipe(Effect.map((contents) => [file, { contents, type: "esm" as const }] as const))
          )
        );
      });
    const apiRoot = path.join(root, ".alchemy/native-pair/bundles/TaxKitApi");
    const websiteRoot = path.join(root, "apps/web/dist/server");
    const apiModules = yield* load(apiRoot);
    const websiteModules = yield* load(websiteRoot);
    const apiWorker = (name: string) => ({
      compatibilityDate: "2026-10-04",
      compatibilityFlags: ["nodejs_compat"],
      bindings: {},
      exports: nativeMcpSessionExports,
      modules: Object.entries(apiModules).map(([p, m]) => ({ path: path.join(apiRoot, p), contents: m.contents, type: "ESModule" as const })),
      modulesRoot: apiRoot,
      name,
    });
    void apiWorker;
    const env = (name: string) => ({
      ...nativeMcpSessionFixture(name),
      ...nativeLocalModeFixture,
      ...nativeRateFixture("10075"),
      API_PUBLIC_ORIGIN: { type: "json" as const, value: apiOrigin },
      TAXKIT_PUBLICATION_ORIGIN: { type: "json" as const, value: websiteOrigin },
      WEBSITE_PUBLIC_ORIGIN: { type: "json" as const, value: websiteOrigin },
      WORKER_URL: { type: "json" as const, value: apiOrigin },
    });
    const api = (name: string) => ({
      config: {
        compatibilityDate: "2026-10-04",
        compatibilityFlags: ["nodejs_compat"],
        env: env(name),
        exports: nativeMcpSessionExports,
        manifest: { mainModule: "worker.js", modules: apiModules, modulesRoot: apiRoot },
        name,
      },
    });
    const publicApi = yield* Effect.acquireRelease(
      Effect.sync(() => new Miniflare({ cf: false, host: "127.0.0.1", port: 4197, workers: [api("pub")] })),
      (h) => Effect.promise(() => h.dispose())
    );
    const website = yield* Effect.acquireRelease(
      Effect.sync(
        () =>
          new Miniflare({
            cf: false,
            host: "127.0.0.1",
            port: 4196,
            workers: [
              {
                config: {
                  assets: { directory: path.join(root, "apps/web/dist/client"), hasUserWorker: true, runWorkerFirst: false },
                  compatibilityDate: "2026-10-04",
                  compatibilityFlags: ["nodejs_compat"],
                  env: {
                    ...nativeLocalModeFixture,
                    API_PUBLIC_ORIGIN: { type: "json" as const, value: apiOrigin },
                    TAXKIT_API: { type: "worker" as const, worker: "priv" },
                    TAXKIT_PUBLICATION_ORIGIN: { type: "json" as const, value: websiteOrigin },
                    WEBSITE_PUBLIC_ORIGIN: { type: "json" as const, value: websiteOrigin },
                  },
                  manifest: { mainModule: "server.js", modules: websiteModules, modulesRoot: websiteRoot },
                  name: "web",
                },
              },
              api("priv"),
            ],
          })
      ),
      (h) => Effect.promise(() => h.dispose())
    );
    yield* Effect.promise(() => publicApi.ready);
    yield* Effect.promise(() => website.ready);
    const show = (label: string, r: { status: number; headers: Headers; text: () => Promise<string> }) =>
      Effect.promise(() => r.text()).pipe(
        Effect.tap((body) => Effect.sync(() => console.log("PROBE", label, r.status, JSON.stringify([...r.headers]), JSON.stringify(body.slice(0, 400)), body.includes("Documentation page not found"), body.includes("Enter up to 100"))))
      );
    for (const u of [
      "/_serverFn/" + "0".repeat(64),
      "/_serverFn/PRIVATE9",
      "/_serverFn/",
      "/" + "a".repeat(256),
      "/..%2FPRIVATE9",
      "/search?term=%ED%A0%80",
      "/search?term=" + "a".repeat(101),
      "/robots.txt",
    ]) {
      yield* show("GET " + u, yield* Effect.promise(() => website.dispatchFetch(websiteOrigin + u, { headers: { origin: websiteOrigin, "sec-fetch-site": "same-origin", "x-tsr-serverFn": "true" } })));
    }
    yield* show("POST serverFn", yield* Effect.promise(() => website.dispatchFetch(websiteOrigin + "/_serverFn/" + "0".repeat(64), { method: "POST", body: "PRIVATE9", headers: { "content-type": "application/json" } })));
    for (const u of [
      "/api/v1/docs/discovery/robots.txt",
      "/api/v1/docs/page?path=%2F" + "a".repeat(256),
      "/api/v1/docs/page?path=..%2FPRIVATE9",
      "/api/v1/docs/page?path=%2Fstart%2Fquickstart&payload=PRIVATE9",
      "/api/v1/docs/navigation",
    ]) {
      yield* show("API " + u, yield* Effect.promise(() => publicApi.dispatchFetch(apiOrigin + u, { headers: { origin: websiteOrigin } })));
    }
    const browser = yield* Effect.acquireRelease(Effect.promise(() => chromium.launch({ headless: true })), (b) => Effect.promise(() => b.close()));
    const context = yield* Effect.promise(() => browser.newContext());
    yield* Effect.promise(() => context.addCookies([{ name: "taxkit_visitor", value: "1", domain: "127.0.0.1", path: "/" }]));
    const page = yield* Effect.promise(() => context.newPage());
    const seen: Array<unknown> = [];
    page.on("request", (r) => { seen.push(r); });
    yield* Effect.promise(() => page.goto(websiteOrigin + "/start/quickstart"));
    yield* Effect.promise(() => page.waitForLoadState("networkidle"));
    seen.length = 0;
    yield* Effect.promise(() => page.locator('.docs-navigation a[href="/sdk/typescript-sdk"]').click());
    yield* Effect.promise(() => page.getByRole("heading", { exact: true, name: "TypeScript SDK" }).waitFor());
    yield* Effect.promise(() => page.getByRole("link", { exact: true, name: "Search documentation" }).click());
    yield* Effect.promise(() => page.getByRole("heading", { exact: true, name: "Search documentation" }).waitFor());
    yield* Effect.promise(() => page.goto(websiteOrigin + "/"));
    yield* Effect.promise(() => page.getByRole("button", { exact: true, name: "Calculate" }).click());
    yield* Effect.promise(() => page.getByText("$1,301.00", { exact: true }).waitFor());
    for (const r of seen as Array<import("playwright").Request>) {
      const h = yield* Effect.promise(() => r.allHeaders());
      console.log("REQ", r.method(), r.url(), r.isNavigationRequest(), JSON.stringify(h));
    }
    expect(true).toBe(true);
  }).pipe(Effect.scoped, Effect.provide(NodeServices.layer))
);
EOF
